INSERT INTO `categories` VALUES (1,'BÌNH ẮC QUY PIN LITHIUM CHO XE NÂNG ĐIỆN','pin-lithium-xe-nang','battery_charging_full','BÌNH ẮC QUY PIN LITHIUM CHO XE NÂNG ĐIỆN','product',NULL,1,1,'2026-01-27 04:35:06','2026-03-04 05:58:19','2026-03-04 05:58:19'),(2,'HỆ THỐNG CAMERA AI AN TOÀN CHO XE NÂNG VÀ MÁY CÔNG TRÌNH','pin-lithium-nang-luong-mat-troi','solar_power','HỆ THỐNG CAMERA AI AN TOÀN CHO XE NÂNG VÀ MÁY CÔNG TRÌNH','product',NULL,2,1,'2026-01-27 04:35:06','2026-01-30 01:15:49',NULL),(3,'PHỤ TÙNG VÀ LINH KIỆN XE NÂNG VÀ MÁY CÔNG TRÌNH','camera-ai','videocam','PHỤ TÙNG VÀ PHỤ KIỆN XE NÂNG VÀ MÁY CÔNG TRÌNH','product',NULL,3,1,'2026-01-27 04:35:06','2026-03-04 07:01:54',NULL),(4,'DỊCH VỤ SỬA CHỮA, BAO DƯỠNG VÀ CHO THUÊ XE NÂNG','dich-vu-xe-nang','precision_manufacturing',NULL,'service',NULL,1,1,'2026-01-27 04:35:06','2026-03-04 04:29:06',NULL),(5,'Dịch vụ Năng Lượng','dich-vu-nang-luong','bolt',NULL,'service',NULL,2,1,'2026-01-27 04:35:06','2026-01-27 04:35:06',NULL),(6,'Tin tức','tin-tuc','newspaper',NULL,'post',NULL,1,1,'2026-01-27 04:35:06','2026-01-27 04:35:06',NULL),(7,'Dự án','du-an','engineering',NULL,'post',NULL,2,1,'2026-01-27 04:35:06','2026-01-27 04:35:06',NULL),(8,'BÌNH ẮC QUY PIN LITHIUM CHO XE NÂNG ĐIỆN','pin-xe-nang-dien',NULL,'Danh mục bình ắc quy pin lithium cho xe nâng điện cung cấp các giải pháp năng lượng hiện đại dành cho các loại xe nâng điện trong nhà máy, kho bãi và khu công nghiệp. Pin lithium đang dần thay thế ắc quy chì truyền thống nhờ các ưu điểm vượt trội như sạc nhanh, tuổi thọ cao, hiệu suất ổn định và không cần bảo dưỡng.\r\n\r\nCác dòng pin lithium xe nâng được thiết kế với nhiều mức điện áp và dung lượng khác nhau như 24V, 36V, 48V, 72V, 80V…, phù hợp với nhiều dòng xe nâng điện của các hãng phổ biến như Toyota, Komatsu, Doosan, Hyundai, Mitsubishi, TCM, Nichiyu, Heli, Hangcha…\r\n\r\nBình pin lithium xe nâng được trang bị hệ thống quản lý pin thông minh (BMS) giúp kiểm soát điện áp, dòng điện, nhiệt độ và đảm bảo an toàn trong quá trình vận hành. Thiết kế chắc chắn, độ bền cao, dễ lắp đặt và tối ưu cho môi trường làm việc công nghiệp.\r\n\r\nƯu điểm của pin lithium xe nâng:\r\n\r\nTuổi thọ cao gấp 3 – 5 lần so với ắc quy chì\r\n\r\nSạc nhanh, có thể sạc trong thời gian nghỉ\r\n\r\nKhông cần bảo dưỡng, không châm nước\r\n\r\nHiệu suất cao, tiết kiệm điện năng\r\n\r\nGiảm chi phí vận hành và tăng thời gian hoạt động của xe nâng\r\n\r\nNMT Technical Co., Ltd cung cấp các giải pháp pin lithium cho xe nâng điện, trạm sạc nhanh và các thiết bị liên quan, kèm theo dịch vụ tư vấn, lắp đặt và bảo hành chuyên nghiệp.','product',NULL,0,1,'2026-03-01 19:52:26','2026-03-04 06:01:41',NULL),(9,'BỘ SẠC - TRẠM SAC XE NÂNG ĐIỆN','bo-sac-xe-dien',NULL,NULL,'product',NULL,0,1,'2026-03-01 19:52:32','2026-03-04 04:28:14',NULL),(10,'Phụ Tùng Oto Hyundai','phu-tung-oto-hyundai',NULL,'NMT TECHNICAL CO., LTD tự hào là đơn vị cung cấp phụ tùng ô tô và dầu nhớt Hyundai uy tín tại Việt Nam. Với phương châm “Uy tín – Nhiệt tình – Trách nhiệm”, NMT cam kết mang đến cho khách hàng sản phẩm chất lượng cao, giá thành cạnh tranh và dịch vụ hỗ trợ tận tâm.','product',NULL,4,1,'2026-03-17 05:07:49','2026-03-17 05:07:49',NULL),(11,'PHỤ TÙNG  OTO HYUNDAI','bao-cao-ton-kho-theo-kho-tst',NULL,NULL,'product',NULL,0,1,'2026-03-18 06:01:06','2026-03-18 19:57:21',NULL),(12,'Báo cáo tồn kho theo kho TST','bao-cao-ton-kho-theo-kho-tst-2',NULL,NULL,'product',NULL,0,1,'2026-03-18 20:01:20','2026-03-18 20:01:20',NULL);
/*!40000 ALTER TABLE `categories` ENABLE KEYS */;
UNLOCK TABLES;

