INSERT INTO `services` VALUES (1,NULL,'Cho thuê xe nâng','cho-thue-xe-nang','local_shipping','Dịch vụ cho thuê xe nâng ngắn hạn và dài hạn với giá cả cạnh tranh','<p>Chúng tôi cung cấp dịch vụ cho thuê xe nâng linh hoạt theo nhu cầu của khách hàng.</p>',NULL,1,1,'2026-01-27 04:35:06','2026-01-27 04:35:06',NULL),(2,NULL,'Bảo trì & Sửa chữa','bao-tri-sua-chua','build','Dịch vụ bảo trì định kỳ và sửa chữa xe nâng tận nơi','<p>Đội ngũ kỹ thuật viên chuyên nghiệp sẵn sàng hỗ trợ bảo trì và sửa chữa 24/7.</p>',NULL,2,1,'2026-01-27 04:35:06','2026-01-27 04:35:06',NULL),(3,NULL,'Tư vấn giải pháp năng lượng','tu-van-giai-phap-nang-luong','lightbulb','Tư vấn và thiết kế hệ thống năng lượng mặt trời cho doanh nghiệp','<p>Chuyên gia của chúng tôi sẽ tư vấn giải pháp năng lượng phù hợp nhất cho doanh nghiệp của bạn.</p>',NULL,3,1,'2026-01-27 04:35:06','2026-01-27 04:35:06',NULL),(4,NULL,'Lắp đặt hệ thống pin','lap-dat-he-thong-pin','engineering','Dịch vụ lắp đặt và chuyển đổi hệ thống pin lithium cho xe nâng','<p>Chúng tôi cung cấp dịch vụ lắp đặt và nâng cấp hệ thống pin lithium cho xe nâng.</p>',NULL,4,1,'2026-01-27 04:35:06','2026-01-27 04:35:06',NULL),(5,NULL,'Đào tạo vận hành','dao-tao-van-hanh','school','Đào tạo nhân viên vận hành xe nâng an toàn và hiệu quả','<p>Khóa đào tạo chuyên nghiệp giúp nhân viên vận hành xe nâng an toàn.</p>',NULL,5,1,'2026-01-27 04:35:06','2026-01-27 04:35:06',NULL),(6,NULL,'Cung cấp phụ tùng','cung-cap-phu-tung','inventory_2','Phụ tùng xe nâng chính hãng với giá ưu đãi','<p>Cung cấp đầy đủ phụ tùng thay thế cho các loại xe nâng phổ biến.</p>',NULL,6,1,'2026-01-27 04:35:06','2026-01-27 04:35:06',NULL);
