INSERT INTO `sliders` VALUES (1,'Pin Lithium cho xe nâng','Nâng cấp hiệu suất – Giảm chi phí','Pin lithium cho xe nâng giúp sạc nhanh, dùng lâu, không bảo dưỡng, an toàn và thân thiện môi trường hơn ắc quy truyền thống.','Xem sản phẩm','/san-pham','photos/1/screenshot_1770098676.png',1,1,'2026-01-27 04:35:07','2026-02-02 23:05:15',NULL),(2,'Dịch vụ Xe Nâng Chuyên Nghiệp','Cho thuê - Bảo trì - Sửa chữa','Đội ngũ kỹ thuật viên giàu kinh nghiệm, hỗ trợ 24/7','Liên hệ ngay','/lien-he',NULL,2,1,'2026-01-27 04:35:07','2026-02-02 20:14:11',NULL);
