INSERT INTO `social_posts` VALUES (1,'facebook','Lắp đặt Pin Lithium 48V 560Ah cho xe nâng điện tại Vĩnh Phúc','NMT Technical Co., Ltd vừa hoàn thành lắp đặt hệ thống pin lithium 48V 560Ah cho xe nâng điện tại kho bãi của khách hàng ở Vĩnh Phúc.\r\n\r\nPin lithium giúp xe nâng sạc nhanh, hoạt động ổn định, không cần bảo dưỡng và tăng hiệu suất làm việc, là giải pháp thay thế tối ưu cho ắc quy chì truyền thống.\r\n\r\nXin cảm ơn quý khách hàng đã tin tưởng lựa chọn giải pháp pin lithium xe nâng của NMT. Chúng tôi luôn sẵn sàng tư vấn, lắp đặt và hỗ trợ kỹ thuật trên toàn quốc.','photos/shares/z7585978590239_3d871998f8f5df1b9d00e1b9c9da5fc4.jpg',NULL,'https://www.facebook.com/share/p/1RJAxKUra6/?mibextid=wwXIfr',1,1,'2026-01-27 08:52:41','2026-03-04 06:38:23');
/*!40000 ALTER TABLE `social_posts` ENABLE KEYS */;
UNLOCK TABLES;

